using System;using System.Linq;using UnityEngine;using UnityEngine.UI;using UnityEditor;using UnityEditor.SceneManagement;
public class FixDecorUI084 {public static string Main(){var root=GameObject.Find("Castle_Services_Prototype").transform;var h=root.Find("03_Service_Houses/04_Professions");var d=h.Find("24_Armory_Wall_Decor");foreach(Transform t in d){if(!t.name.Contains("Shield"))continue;float y=t.name.StartsWith("Rear")?180:t.name.StartsWith("Left")?90:-90;t.localScale=Vector3.one;t.localRotation=Quaternion.Euler(90,y,0);var rs=t.GetComponentsInChildren<Renderer>();var b=rs[0].bounds;foreach(var r in rs.Skip(1))b.Encapsulate(r.bounds);t.localScale*= (t.name.StartsWith("Rear")?1f:.8f)/b.size.y;b=rs[0].bounds;foreach(var r in rs.Skip(1))b.Encapsulate(r.bounds);Vector3 p=t.name.StartsWith("Rear")?new Vector3(0,2.8f,3.45f):new Vector3(t.name.StartsWith("Left")?-2.64f:2.64f,2.8f,.3f);t.position+=h.TransformPoint(p)-b.center;}
 string s="";foreach(var t in root.GetComponentsInChildren<Text>(true).Where(t=>t.name=="Localized_Text")){t.resizeTextMaxSize=300;t.fontSize=140;s+=t.text+" rect="+t.rectTransform.rect.size+" pref="+t.preferredWidth+","+t.preferredHeight+"\n";}Canvas.ForceUpdateCanvases();EditorSceneManager.MarkSceneDirty(h.gameObject.scene);EditorSceneManager.SaveScene(h.gameObject.scene);return s;}}
